(* [comment removed for export] *)
Definition unmap_cells (m : amem) : Prop :=
     rw_cells bsegs m 0xb2118 [C8 (Z_to_bv 64 0x14be28)]
  /\ rw_cells bsegs m 0x14beb8 [C8 (Z_to_bv 64 0)].

